public class OrderProcessor
{
    private readonly AppDbContext _context;
    private readonly IPaymentGateway _paymentGateway;
    private readonly IEmailService _emailService;

    public OrderProcessor(AppDbContext context, IPaymentGateway paymentGateway, IEmailService emailService)
    {
        _context = context;
        _paymentGateway = paymentGateway;
        _emailService = emailService;
    }

    public void ProcessOrder(Order order)
    {
        // Step 1: Validate inventory
        foreach (var item in order.Items)
        {
            var stock = _context.Inventory.First(i => i.ProductId == item.ProductId);
            if (stock.Quantity < item.Quantity)
                throw new InvalidOperationException("Insufficient stock");
        }

        // Step 2: Charge payment
        var paymentResult = _paymentGateway.Charge(order.CustomerId, order.Total);
        if (!paymentResult.Succeeded)
            throw new PaymentFailedException(paymentResult.Error);

        // Step 3: Update inventory
        foreach (var item in order.Items)
        {
            stock.Quantity -= item.Quantity;
            _context.Inventory.Update(stock);
        }

        // Step 4: Save order and send confirmation
        order.Status = OrderStatus.Confirmed;
        _context.Orders.Add(order);
        _context.SaveChanges();

        _emailService.SendConfirmation(order.CustomerId, order.Id);
    }
}

public class AsyncOrderProcessor
{
    private readonly AppDbContext _context;
    private readonly IPaymentGateway _paymentGateway;
    private readonly IEmailService _emailService;
    private readonly IInventoryService _inventoryService;

    public async Task<OrderResult> ProcessOrderAsync(CreateOrderRequest request, CancellationToken ct)
    {
