        // Step 2: Create and save order
        var order = Order.Create(request);
        await _context.Orders.AddAsync(order, ct);
        await _context.SaveChangesAsync(ct);

        // Step 3: Charge payment
        var paymentTask = _paymentGateway.ChargeAsync(request.CustomerId, order.Total, ct);
        await paymentTask;
        if (!paymentTask.Result.Succeeded)
            return OrderResult.Failure(paymentTask.Result.Error);

        // Step 4: Reserve inventory and send email in parallel
        var reserveTask = _inventoryService.ReserveAsync(order.Id, request.Items, ct);
        var emailTask = _emailService.SendConfirmationAsync(request.CustomerId, order.Id, ct);
        await Task.WhenAll(reserveTask, emailTask);

        return OrderResult.Success(order);
    }
}

public class OrderConfirmationWorker : BackgroundService
{
    private readonly Channel<OrderConfirmation> _channel;
    private readonly IEmailService _emailService;
    private readonly ILogger<OrderConfirmationWorker> _logger;
    private const int MaxConcurrency = 4;

    public OrderConfirmationWorker(Channel<OrderConfirmation> channel, IEmailService emailService, ILogger<OrderConfirmationWorker> logger)
    {
        _channel = channel;
        _emailService = emailService;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var confirmation in _channel.Reader.ReadAllAsync(stoppingToken))
        {
            try
            {
                await _emailService.SendOrderConfirmationAsync(confirmation.CustomerId, confirmation.OrderId, stoppingToken);
                _logger.LogInformation("Sent confirmation email for order {OrderId}", confirmation.OrderId);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to send confirmation email for order {OrderId}", confirmation.OrderId);
            }
        }
    }
}

// Controller publishes to the channel and returns immediately
[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    private readonly OrderService _service;
    private readonly ChannelWriter<OrderConfirmation> _channelWriter;

    [HttpPost]
    public async Task<ActionResult<OrderResult>> Create([FromBody] CreateOrderRequest request)
    {
        var result = await _service.CreateAsync(request);
        if (result.IsSuccess)
            await _channelWriter.WriteAsync(new OrderConfirmation(result.OrderId, result.CustomerId));
        return result.IsSuccess ? CreatedAtRoute(...) : BadRequest(result.Error);
    }
}
